16	package io.github.microcks.web;
17	
18	import io.github.microcks.service.SpanStorageService;
19	import io.opentelemetry.sdk.trace.ReadableSpan;
20	import io.opentelemetry.sdk.trace.data.SpanData;
21	import org.springframework.http.ResponseEntity;
22	import org.springframework.web.bind.annotation.DeleteMapping;
23	import org.springframework.web.bind.annotation.GetMapping;
24	import org.springframework.web.bind.annotation.PathVariable;
25	import org.springframework.web.bind.annotation.RequestMapping;
26	import org.springframework.web.bind.annotation.RequestParam;
27	import org.springframework.web.bind.annotation.RestController;
28	
29	import java.util.List;
30	import java.util.Map;
31	import java.util.Set;
32	
33	/**
34	 * REST controller for accessing trace and span information stored by the SpanStorageService. Provides endpoints to
35	 * retrieve traces, spans
36	 *
37	 */
38	@RestController
39	@RequestMapping("/api/traces")
40	public class TracingController {
41	
42	   private final SpanStorageService spanStorageService;
43	
44	
45	   public TracingController(SpanStorageService spanStorageService) {
46	      this.spanStorageService = spanStorageService;
47	   }
48	
49	   /**
50	    * Get all trace IDs currently stored.
51	    *
52	    * @return Set of trace IDs
53	    */
54	   @GetMapping
55	   public ResponseEntity<Set<String>> getAllTraceIds() {
56	      return ResponseEntity.ok(spanStorageService.getAllTraceIds());
57	   }
58	
59	   /**
60	    * Get all spans for a specific trace ID.
61	    *
62	    * @param traceId The trace ID to look up
63	    * @return List of spans for the trace
64	    */
65	   @GetMapping("/{traceId}/spans")
66	   public ResponseEntity<List<SpanData>> getSpansForTrace(@PathVariable("traceId") String traceId) {
67	      List<ReadableSpan> spans = spanStorageService.getSpansForTrace(traceId);
68	      if (spans.isEmpty()) {
69	         return ResponseEntity.notFound().build();
70	      }
71	      return ResponseEntity.ok(spans.stream().map(ReadableSpan::toSpanData).toList());
72	   }
73	
74	   @GetMapping("/operations/spans")
75	   public ResponseEntity<List<List<ReadableSpan>>> getSpansForOperation(@RequestParam("serviceName") String serviceName,
76	         @RequestParam("operationName") String operationName) {
77	      List<String> traceIds = spanStorageService
78	            .queryTraceIdsBySpanAttributes(Map.of(io.opentelemetry.api.common.AttributeKey.stringKey("service.name"),
79	                  serviceName, io.opentelemetry.api.common.AttributeKey.stringKey("operation.name"), operationName));
80	      if (traceIds.isEmpty()) {
81	         return ResponseEntity.notFound().build();
82	      }
83	
84	      List<List<ReadableSpan>> spansByTraceId = traceIds.stream().map(spanStorageService::getSpansForTrace).toList();
85	
86	
87	      return ResponseEntity.ok(spansByTraceId);
88	   }
89	
90	   /**
91	    * Clear all stored traces and spans.
92	    *
93	    * @return Success message
94	    */
95	   @DeleteMapping
96	   public ResponseEntity<String> clearAllTraces() {
97	      spanStorageService.clearAll();
98	      return ResponseEntity.ok("All traces and spans have been cleared");
99	   }
100	
101	}
102

