/**
 * Manages live subscriptions to trace events over Server-Sent Events (SSE). Clients register an {@link SseEmitter}
 * along with filter criteria and receive an event whenever a matching trace is updated.
 */
@Component
public class TraceSubscriptionManager {

   private static final Logger log = LoggerFactory.getLogger(TraceSubscriptionManager.class);

   /** Name of the SSE event used to keep connections alive. */
   private static final String HEARTBEAT_EVENT = "heartbeat";
   /** Name of the SSE event carrying trace updates. */
   private static final String TRACE_EVENT = "trace";

   private final SpanStorageService spanStorageService;

   /** Thread-safe list of active subscriptions. */
   private final List<TraceSubscription> subscriptions = new CopyOnWriteArrayList<>();

   /**
    * Build a new TraceSubscriptionManager.
    *
    * @param spanStorageService The service used to look up spans for a trace
    */
   public TraceSubscriptionManager(SpanStorageService spanStorageService) {
      this.spanStorageService = spanStorageService;
   }

   /**
    * Registers an emitter for a filtered live stream of trace events. A heartbeat event is sent immediately to confirm
    * the connection.
    *
    * @param emitter       The SSE emitter to register
    * @param serviceName   The service name filter pattern (may be a wildcard)
    * @param operationName The operation name filter pattern (may be a wildcard)
    * @param clientAddress The client address filter pattern (may be a wildcard)
    */
   public void subscribe(SseEmitter emitter, String serviceName, String operationName, String clientAddress) {
      TraceSubscription subscription = new TraceSubscription(emitter, serviceName, operationName, clientAddress);
      subscriptions.add(subscription);

      emitter.onCompletion(() -> subscriptions.remove(subscription));
      emitter.onTimeout(() -> subscriptions.remove(subscription));
      emitter.onError(t -> subscriptions.remove(subscription));

      // Immediately send a heartbeat so that clients know the subscription is live.
      sendHeartbeat(subscription);
