      if (spans == null || spans.isEmpty()) {
         // Nothing to stream if there are no spans for this trace.
         return;
      }

      TraceEvent fullEvent = SpanFilterUtil.extractTraceEvent(event.traceId(), spans);

      for (TraceSubscription subscription : subscriptions) {
         if (SpanFilterUtil.matchesTraceEvent(fullEvent, subscription.serviceName(), subscription.operationName(),
               subscription.clientAddress())) {
            sendTraceEvent(subscription, fullEvent);
