      } catch (IOException e) {
         log.debug("Failed to send trace event, completing emitter: {}", e.getMessage());
         subscription.emitter().complete();
      }
   }

   /**
    * Sends a heartbeat to a single subscriber, completing its emitter on failure.
    */
   private void sendHeartbeat(TraceSubscription subscription) {
      try {
         subscription.emitter().send(SseEmitter.event().name(HEARTBEAT_EVENT).data(HEARTBEAT_EVENT));
      } catch (IOException e) {
         log.debug("Failed to send heartbeat, completing emitter: {}", e.getMessage());
         subscription.emitter().complete();
